<?php
require_once __DIR__.'/includes/functions.php'; ensure_product_media_table();
$slug=$_GET['slug']??'';$st=db()->prepare('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.slug=? AND p.status="active"');$st->execute([$slug]);$p=$st->fetch();if(!$p){http_response_code(404);require __DIR__.'/404.php';exit;}
$gallery=db()->prepare('SELECT image_url FROM product_images WHERE product_id=? ORDER BY sort_order,id');$gallery->execute([$p['id']]);$images=$gallery->fetchAll(PDO::FETCH_COLUMN);if(!$images)$images=json_decode($p['images']?:'[]',true)?:[product_image($p)];$related=db()->prepare('SELECT * FROM products WHERE category_id=? AND id!=? AND status="active" LIMIT 4');$related->execute([$p['category_id'],$p['id']]);$title=$p['name'].' | ALAN';include __DIR__.'/includes/header.php';
?><div class="page"><div class="product-detail"><div class="product-gallery"><div class="gallery-main"><button class="gallery-arrow gallery-prev" type="button" aria-label="Previous image">‹</button><img id="product-main-image" src="<?=e($images[0])?>" alt="<?=e($p['name'])?>"><button class="gallery-arrow gallery-next" type="button" aria-label="Next image">›</button><span class="gallery-count"><b id="gallery-current">1</b> / <?=count($images)?></span></div><?php if(count($images)>1):?><div class="gallery-thumbs"><?php foreach($images as $i=>$image):?><button class="gallery-thumb <?=$i===0?'active':''?>" type="button" data-index="<?=$i?>"><img src="<?=e($image)?>" alt="<?=e($p['name'])?>"></button><?php endforeach;?></div><?php endif;?></div><div><p class="eyebrow"><?=e($p['category_name'])?></p><h1><?=e($p['name'])?></h1><p>★★★★★ <small>(<?=e($p['rating_count'])?>)</small></p><div class="price"><?=money((float)$p['price'])?> <?php if($p['old_price']):?><del><?=money((float)$p['old_price'])?></del><?php endif;?></div><p class="description"><?=nl2br(e($p['description']))?></p><form class="options" id="buy-form"><input type="hidden" name="product_id" value="<?=$p['id']?>"><label>اللون</label><?php foreach(explode(',',$p['color']) as $i=>$color):?><button type="button" class="<?=$i===0?'selected':''?>"><?=e(trim($color))?></button><?php endforeach;?><label>المقاس</label><?php foreach(explode(',',$p['sizes']) as $i=>$size):?><button type="button" class="<?=$i===0?'selected':''?>"><?=e(trim($size))?></button><?php endforeach;?></form><div class="add-cart"><input name="qty" form="buy-form" type="number" value="1" min="1" max="<?=e($p['stock'])?>"><button class="btn" data-cart="<?=$p['id']?>">أضيفي للحقيبة</button><a class="btn buy" href="<?=base('checkout.php?product='.$p['id'])?>">اشتري الآن</a></div></div></div></div><section class="section products-bg"><div class="heading"><h2>قد يعجبكِ أيضاً</h2></div><div class="grid"><?php foreach($related as $p)include __DIR__.'/views/product-card.php';?></div></section><script>document.querySelectorAll('.options button').forEach(button=>button.onclick=()=>{button.parentElement.querySelectorAll('button').forEach(item=>item.classList.remove('selected'));button.classList.add('selected')});const images=<?=json_encode(array_values($images),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;let index=0;const main=document.querySelector('#product-main-image'),count=document.querySelector('#gallery-current');function changeImage(next){index=(next+images.length)%images.length;main.src=images[index];count.textContent=index+1;document.querySelectorAll('.gallery-thumb').forEach((thumb,i)=>thumb.classList.toggle('active',i===index));}document.querySelector('.gallery-prev')?.addEventListener('click',()=>changeImage(index-1));document.querySelector('.gallery-next')?.addEventListener('click',()=>changeImage(index+1));document.querySelectorAll('.gallery-thumb').forEach(thumb=>thumb.addEventListener('click',()=>changeImage(Number(thumb.dataset.index))));let startX=0;main.addEventListener('touchstart',event=>startX=event.changedTouches[0].screenX,{passive:true});main.addEventListener('touchend',event=>{const distance=event.changedTouches[0].screenX-startX;if(Math.abs(distance)>35)changeImage(index+(distance>0?-1:1));},{passive:true});</script><?php include __DIR__.'/includes/footer.php'; ?>
